<script setup>
import {computed,ref,watch} from 'vue';
import {api,yuan,units,today,cents} from './api.js';
const props=defineProps({page:String,state:Object,filter:Object});const emit=defineEmits(['changed','navigate']);
const accountId=ref(''),month=ref(today().slice(0,7)),query=ref(''),status=ref(''),kind=ref('trial'),subjectFilter=ref('');
const modal=ref(''),form=ref({}),error=ref(''),busy=ref(false),result=ref(null),financial=ref(null),viewed=ref(null),loadingReport=ref(false);
let reportSequence=0;
const accounting=computed(()=>props.state.accounting||{}),accounts=computed(()=>accounting.value.accounts||[]);
const account=computed(()=>accounts.value.find(a=>a.id===Number(accountId.value)));
const cname=id=>(props.state.customers||[]).find(c=>c.id===Number(id))?.name||'—';
const subjects=computed(()=>(accounting.value.subjects||[]).filter(s=>s.account_id===Number(accountId.value)));
const leafSubjects=computed(()=>subjects.value.filter(s=>s.active!==0&&s.enabled!==0&&!subjects.value.some(c=>c.parent_code===s.code)));
const sname=code=>subjects.value.find(s=>s.code===code)?.name||code;
const periods=computed(()=>(accounting.value.periods||[]).filter(p=>p.account_id===Number(accountId.value)).sort((a,b)=>String(a.month).localeCompare(String(b.month))));
const enabled=a=>a&&(a.enabled===1||['active','启用','已启用','启用中'].includes(a.status));
const vouchers=computed(()=>(accounting.value.vouchers||[]).filter(v=>v.account_id===Number(accountId.value)&&(!month.value||v.date.startsWith(month.value))&&(!status.value||v.status===status.value)&&(!query.value||`${v.summary} ${v.word}-${v.number} ${(v.entries||[]).map(e=>e.summary).join(' ')}`.includes(query.value))));
const titles={accounts:['账套设置','每个客户独立账套，管理科目、期初余额和启用状态。'],vouchers:['凭证管理','借贷分录平衡校验，审核后锁定，账簿实时更新。'],ledgers:['账簿查询','根据已审核凭证与期初余额，查看客户账簿。'],financial:['财务报表','按账套和期间汇总，核对资产、负债与利润。'],closing:['期末处理','损益结转、凭证审核和按序结账。']};
const title=computed(()=>titles[props.page]||titles.accounts);
watch(()=>[props.state.accounting,props.filter],()=>{
 const fromCustomer=props.filter?.customer_id&&accounts.value.find(a=>a.customer_id===Number(props.filter.customer_id));
 if(props.filter?.customer_id&&!fromCustomer)accountId.value='';
 else if(fromCustomer)accountId.value=fromCustomer.id;
 else if(!accounts.value.some(a=>a.id===Number(accountId.value)))accountId.value=accounts.value[0]?.id||'';
 if(props.filter?.month)month.value=props.filter.month;
},{immediate:true});
watch(()=>props.page,()=>{error.value='';modal.value='';query.value='';status.value='';});
watch(()=>props.filter,()=>{if(props.page==='vouchers'&&props.filter?.action==='new'){if(enabled(account.value))openVoucher();else error.value='请先为所选客户建立并启用账套，再录入凭证';}},{immediate:true});
watch([accountId,month,kind,()=>props.page,()=>props.state.accounting],()=>loadReport(),{immediate:true});
async function run(fn,msg){busy.value=true;error.value='';try{const r=await fn();emit('changed',msg);return r;}catch(e){error.value=e.message;return null;}finally{busy.value=false;}}
async function loadReport(){
 const sequence=++reportSequence;
 if(!accountId.value||!['ledgers','financial'].includes(props.page)){result.value=null;financial.value=null;return;}
 loadingReport.value=true;error.value='';
 try{const value=await api(`/${props.page==='ledgers'?'ledger':'financial'}?account_id=${accountId.value}&month=${month.value}&kind=${kind.value}`);if(sequence===reportSequence){if(props.page==='ledgers')result.value=value;else financial.value=value;}}
 catch(e){if(sequence===reportSequence){error.value=e.message;result.value=null;financial.value=null;}}finally{if(sequence===reportSequence)loadingReport.value=false;}
}
function openAccount(){modal.value='account';error.value='';form.value={customer_id:(props.state.customers||[]).find(c=>!accounts.value.some(a=>a.customer_id===c.id))?.id||'',name:'',start_month:today().slice(0,7)};}
async function saveAccount(){await run(async()=>{const r=await api('/accounts',{...form.value,customer_id:Number(form.value.customer_id)});accountId.value=r.id;month.value=form.value.start_month;modal.value='';},'账套已建立，接下来录入期初余额并启用');}
function openOpening(){modal.value='opening';error.value='';const rows=(accounting.value.openings||[]).filter(o=>o.account_id===Number(accountId.value)).map(o=>({...o,debit:units(o.debit_cents),credit:units(o.credit_cents)}));form.value={rows:rows.length?rows:[{subject_code:leafSubjects.value[0]?.code||'',debit:'0.00',credit:'0.00'},{subject_code:'3001',debit:'0.00',credit:'0.00'}]};}
const toCents=v=>{try{return cents(v||'0');}catch{return 0;}};
const balance=computed(()=>{const rows=form.value.entries||form.value.rows||[];const debit=rows.reduce((s,r)=>s+toCents(r.debit),0),credit=rows.reduce((s,r)=>s+toCents(r.credit),0);return {debit,credit,difference:debit-credit};});
async function saveOpening(){await run(async()=>{const rows=form.value.rows.map(r=>({subject_code:r.subject_code,debit_cents:cents(r.debit||'0'),credit_cents:cents(r.credit||'0')}));await api(`/accounts/${accountId.value}/openings`,{rows},'PUT');modal.value='';},'期初余额已保存');}
async function enableAccount(){if(!confirm('启用前请核对期初余额。启用后期初余额将冻结，不能继续修改。'))return;await run(()=>api(`/accounts/${accountId.value}/enable`,{}),'账套已启用');}
function openSubject(s){error.value='';modal.value='subject';form.value=s?{...s}:{account_id:Number(accountId.value),code:'',name:'',type:'资产',direction:'借',parent_code:'',active:1};}
async function saveSubject(){await run(async()=>{await api('/subjects'+(form.value.id?'/'+form.value.id:''),form.value,form.value.id?'PUT':'POST');modal.value='';},'会计科目已保存');}
function openVoucher(v){
 error.value='';modal.value='voucher';
 if(v){form.value={...JSON.parse(JSON.stringify(v)),entries:v.entries.map(e=>({...e,debit:units(e.debit_cents),credit:units(e.credit_cents)}))};return;}
 form.value={account_id:Number(accountId.value),date:month.value===today().slice(0,7)?today():month.value+'-01',word:'记',summary:'',status:'草稿',entries:[{subject_code:'',summary:'',debit:'',credit:''},{subject_code:'',summary:'',debit:'',credit:''}]};
}
async function saveVoucher(){await run(async()=>{const data={...form.value,account_id:Number(accountId.value),entries:form.value.entries.map(e=>({subject_code:e.subject_code,summary:e.summary,debit_cents:cents(e.debit||'0'),credit_cents:cents(e.credit||'0')}))};await api('/vouchers'+(data.id?'/'+data.id:''),data,data.id?'PUT':'POST');modal.value='';},'凭证已保存');}
async function audit(v,undo=false){await run(()=>api(`/vouchers/${v.id}/${undo?'unaudit':'audit'}`,{}),undo?'已撤销审核':'凭证已审核，账簿和报表已更新');}
async function remove(v){if(!confirm(`删除 ${v.word}-${v.number}？此操作只适用于未审核凭证。`))return;await run(()=>api('/vouchers/'+v.id,undefined,'DELETE'),'凭证已删除');}
async function periodAction(p,action){const label={carryforward:'生成或重做损益结转凭证',close:'结账',unclose:'反结账'}[action];if(!confirm(`${p.month} ${label}？${action==='close'?'结账后本期凭证将锁定。':''}`))return;await run(()=>api(`/accounts/${accountId.value}/periods/${p.month}/${action}`,{}),`${p.month} ${label}完成`);}
async function addYear(){const year=(periods.value.length?Math.max(...periods.value.map(p=>Number(p.month.slice(0,4)))):Number(today().slice(0,4)))+1;await run(()=>api(`/accounts/${accountId.value}/periods`,{year}),'下一年度会计期间已建立');}
const closed=p=>Boolean(p.is_closed||p.closed);
function exportCsv(rows,name){if(!rows?.length)return;const keys=Object.keys(rows[0]);const csv=[keys,...rows.map(r=>keys.map(k=>r[k]??''))].map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();URL.revokeObjectURL(url);}
const ledgerLabels={code:'科目编码',subject_code:'科目编码',name:'科目名称',subject_name:'科目名称',type:'类别',date:'日期',word:'凭证字',number:'凭证号',summary:'摘要',direction:'方向',debit_cents:'本期借方',credit_cents:'本期贷方',opening_net_cents:'期初净额',closing_net_cents:'期末净额',opening_debit_cents:'期初借方',opening_credit_cents:'期初贷方',closing_debit_cents:'期末借方',closing_credit_cents:'期末贷方',balance_cents:'余额',begin_cents:'期初余额',end_cents:'期末余额',voucher_no:'凭证号',begin_debit_cents:'期初借方',begin_credit_cents:'期初贷方',end_debit_cents:'期末借方',end_credit_cents:'期末贷方',voucher_count:'凭证数',begin_balance_cents:'期初余额',end_balance_cents:'期末余额'};
const ledgerRows=computed(()=>(result.value?.rows||[]).filter(r=>!subjectFilter.value||`${r.subject_code||r.code||''} ${r.name||r.subject_name||''}`.includes(subjectFilter.value)));
const ledgerColumns=computed(()=>ledgerRows.value.length?Object.keys(ledgerRows.value[0]).filter(k=>!['account_id','id','voucher_id','subject_id','period_id'].includes(k)):[]);
function ledgerExport(){exportCsv(ledgerRows.value.map(r=>Object.fromEntries(ledgerColumns.value.map(k=>[ledgerLabels[k]||k,k.endsWith('_cents')?units(r[k]):r[k]]))),'账簿_'+month.value);}
function financialExport(){const f=financial.value;exportCsv([{项目:'资产合计',金额_元:units(f.balance_sheet.assets_cents)},{项目:'负债合计',金额_元:units(f.balance_sheet.liabilities_cents)},{项目:'权益合计',金额_元:units(f.balance_sheet.equity_cents)},{项目:'本期净利润',金额_元:units(f.income_statement.net_profit_cents)},{项目:'本年净利润',金额_元:units(f.income_statement.ytd_net_profit_cents)}],'财务汇总_'+month.value);}
function printVoucher(v){const w=window.open('','_blank','width=1000,height=700');if(!w){error.value='浏览器拦截了打印窗口，请允许本机页面弹出窗口';return;}const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');w.document.write(`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>记账凭证</title><style>body{font:15px Microsoft YaHei,sans-serif;padding:40px;color:#222}h1{text-align:center}table{width:100%;border-collapse:collapse}td,th{border:1px solid #555;padding:14px}footer{margin-top:24px;display:flex;justify-content:space-between}</style><h1>记账凭证</h1><p>${esc(cname(account.value?.customer_id))}　${esc(v.date)}　${esc(v.word)}-${esc(v.number)}　${esc(v.status)}</p><table><tr><th>摘要</th><th>会计科目</th><th>借方金额</th><th>贷方金额</th></tr>${v.entries.map(e=>`<tr><td>${esc(e.summary||v.summary)}</td><td>${esc(e.subject_code)} ${esc(sname(e.subject_code))}</td><td>${yuan(e.debit_cents)}</td><td>${yuan(e.credit_cents)}</td></tr>`).join('')}<tr><td colspan="2">合计</td><td>${yuan(v.entries.reduce((s,e)=>s+e.debit_cents,0))}</td><td>${yuan(v.entries.reduce((s,e)=>s+e.credit_cents,0))}</td></tr></table><footer><span>本机账务记录</span><span>复核：____________</span><span>制单：____________</span></footer></html>`);w.document.close();w.focus();w.print();}
</script>

<template>
 <section class="accounting-view">
  <div class="page-heading"><div><h1 class="page-title">{{title[0]}}</h1><p class="page-description">{{title[1]}}</p></div><div class="actions"><button v-if="page==='accounts'" class="btn btn-primary" @click="openAccount">＋ 新建客户账套</button><button v-if="page==='vouchers'" class="btn btn-primary" :disabled="!enabled(account)" @click="openVoucher()">＋ 新增凭证</button></div></div>
  <div v-if="error&&!modal" class="notice error" role="alert">{{error}}</div>
  <div class="card toolbar"><label class="inline-label">客户账套 <select v-model="accountId" aria-label="客户账套"><option value="" disabled>请选择账套</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{cname(a.customer_id)}} · {{a.name}}</option></select></label><label v-if="page!=='accounts'&&page!=='closing'" class="inline-label">会计月份 <input v-model="month" type="month" required aria-label="会计月份"></label><span v-if="account" class="badge" :class="enabled(account)?'success':'warning'">{{enabled(account)?'账套已启用':'待录入期初并启用'}}</span></div>
  <div v-if="!accounts.length" class="card empty-state"><div class="empty-symbol">▥</div><h3>为客户建立独立账套</h3><p>建立账套后，录入期初余额并试算平衡，即可开始记账。</p><button class="btn btn-primary" @click="openAccount">新建客户账套</button></div>
  <div v-else-if="!account" class="card empty-state"><h3>该客户尚未建立账套</h3><p>为当前客户建立独立账套后即可录入凭证。</p><button class="btn btn-primary" @click="openAccount">新建客户账套</button></div>
  <template v-else-if="account">
   <template v-if="page==='accounts'">
    <div class="card settings-card account-overview"><div><h2>{{account.name}}</h2><p>{{cname(account.customer_id)}} · 小企业会计准则 · 启用月份 {{account.start_month}}</p><span class="text-muted">{{subjects.length}} 个预设及自定义科目 · {{periods.length}} 个会计期间</span></div><div class="actions"><button class="btn btn-secondary" :disabled="enabled(account)" @click="openOpening">录入 / 试算期初余额</button><button class="btn btn-primary" :disabled="enabled(account)||busy" @click="enableAccount">{{enabled(account)?'已启用':'试算平衡并启用'}}</button></div></div>
    <div class="card"><div class="table-meta"><h2>会计科目</h2><div class="actions"><input v-model="query" placeholder="搜索编码或科目名称" aria-label="搜索会计科目"><button class="btn btn-secondary" @click="openSubject()">＋ 新增科目</button></div></div><div class="notice compact">一级科目参照小企业会计准则，常用明细为本软件预设，可按客户业务调整。3103 本年利润为系统结转保留科目，不可增设明细。不含进销存或项目核算模块。</div><div class="table-wrap subject-scroll"><table class="data-table"><thead><tr><th>科目编码</th><th>名称</th><th>类别</th><th>余额方向</th><th>可记账</th><th>操作</th></tr></thead><tbody><tr v-for="s in subjects.filter(s=>`${s.code} ${s.name}`.includes(query))" :key="s.id"><td>{{s.code}}</td><td>{{s.name}}</td><td>{{s.type||s.category}}</td><td>{{s.direction}}</td><td><span class="badge" :class="s.active===0?'muted':leafSubjects.some(x=>x.id===s.id)?'success':'muted'">{{s.active===0?'已停用':leafSubjects.some(x=>x.id===s.id)?'末级科目':'上级汇总'}}</span></td><td><button class="table-link" @click="openSubject(s)">编辑</button></td></tr></tbody></table></div></div>
   </template>

   <template v-if="page==='vouchers'">
    <div v-if="!enabled(account)" class="notice">请在账套设置中保存期初余额、试算平衡并启用账套后，再录入凭证。<button class="table-link" @click="emit('navigate','accounts')">前往账套设置</button></div>
    <div class="card toolbar"><input v-model="query" class="search-input" placeholder="搜索凭证号或摘要" aria-label="搜索凭证"><select v-model="status" aria-label="凭证状态"><option value="">全部状态</option><option>草稿</option><option>待复核</option><option>已完成</option></select><button class="btn btn-secondary" @click="exportCsv(vouchers.map(v=>({日期:v.date,凭证字:v.word,凭证号:v.number,摘要:v.summary,借方_元:units(v.entries.reduce((s,e)=>s+e.debit_cents,0)),贷方_元:units(v.entries.reduce((s,e)=>s+e.credit_cents,0)),状态:v.status})),'凭证列表_'+month)">导出 CSV</button></div>
    <div class="card table-wrap"><div class="table-meta">{{month}} · 共 {{vouchers.length}} 张凭证</div><table class="data-table"><thead><tr><th>日期 / 凭证号</th><th>摘要</th><th>借方合计</th><th>贷方合计</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="v in vouchers" :key="v.id"><td>{{v.date}}<small class="cell-sub">{{v.word}}-{{String(v.number).padStart(3,'0')}}</small></td><td><button class="table-link" @click="viewed=v;modal='view'">{{v.summary||'查看凭证'}}</button><small class="cell-sub" v-if="v.source==='carryforward'">系统损益结转</small></td><td class="money">¥{{yuan(v.entries.reduce((s,e)=>s+e.debit_cents,0))}}</td><td class="money">¥{{yuan(v.entries.reduce((s,e)=>s+e.credit_cents,0))}}</td><td><span class="badge" :class="v.status==='已完成'?'success':v.status==='待复核'?'warning':'muted'">{{v.status}}</span></td><td><div class="actions"><button class="table-link" @click="viewed=v;modal='view'">查看</button><button v-if="v.status!=='已完成'" class="table-link" @click="openVoucher(v)">编辑</button><button v-if="v.status!=='已完成'" class="table-link" :disabled="busy" @click="audit(v)">审核</button><button v-else class="table-link" :disabled="busy" @click="audit(v,true)">反审核</button><button class="table-link" @click="printVoucher(v)">打印</button><button v-if="v.status!=='已完成'" class="table-link danger-text" :disabled="busy" @click="remove(v)">删除</button></div></td></tr></tbody></table><div v-if="!vouchers.length" class="empty-state">本月暂无凭证。已审核凭证才会计入账簿和财报。</div></div>
   </template>

   <template v-if="page==='ledgers'">
    <div class="tabs ledger-tabs"><button v-for="(label,key) in {general:'总账',detail:'明细账',journal:'现金 / 银行日记账',trial:'科目余额表',summary:'凭证汇总表'}" :key="key" :class="{active:kind===key}" @click="kind=key">{{label}}</button></div>
    <div class="card toolbar"><input v-model="subjectFilter" class="search-input" aria-label="筛选科目" placeholder="筛选科目编码或名称"><span class="text-muted">仅统计已审核凭证</span><button class="btn btn-secondary" :disabled="!ledgerRows.length" @click="ledgerExport">导出当前账簿 CSV</button></div>
    <div class="card table-wrap"><div v-if="loadingReport" class="empty-state">正在读取账簿…</div><table v-else-if="ledgerRows.length" class="data-table"><thead><tr><th v-for="k in ledgerColumns" :key="k">{{ledgerLabels[k]||k}}</th></tr></thead><tbody><tr v-for="(r,i) in ledgerRows" :key="i"><td v-for="k in ledgerColumns" :key="k" :class="{'money':k.endsWith('_cents')}">{{k.endsWith('_cents')?yuan(r[k]):r[k]}}</td></tr></tbody></table><div v-else class="empty-state">此期间暂无账簿记录，或筛选条件没有匹配结果。</div></div>
   </template>

   <template v-if="page==='financial'">
    <div v-if="loadingReport" class="card empty-state">正在汇总财务记录…</div>
    <template v-else-if="financial"><div class="notice">{{financial.note||'基础财务汇总，以期初余额与已审核凭证为准，正式对外报表请由会计复核。'}}</div><div class="actions report-export"><button class="btn btn-secondary" @click="financialExport">导出财务汇总 CSV</button></div><div class="report-stats"><div class="card"><span>资产合计</span><strong>¥{{yuan(financial.balance_sheet.assets_cents)}}</strong></div><div class="card"><span>负债合计</span><strong>¥{{yuan(financial.balance_sheet.liabilities_cents)}}</strong></div><div class="card"><span>所有者权益</span><strong>¥{{yuan(financial.balance_sheet.equity_cents)}}</strong></div><div class="card"><span>本期净利润</span><strong>¥{{yuan(financial.income_statement.net_profit_cents)}}</strong></div></div><div class="financial-grid"><article class="card settings-card"><h2>资产负债基础表</h2><p :class="financial.balance_sheet.difference_cents===0?'success-text':'danger-text'">{{financial.balance_sheet.difference_cents===0?'✓ 资产 = 负债 + 所有者权益':'试算差额 ¥'+yuan(financial.balance_sheet.difference_cents)}}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>科目</th><th>期末余额</th></tr></thead><tbody><tr v-for="(r,i) in financial.balance_sheet.rows||[]" :key="i"><td>{{r.name||r.subject_name}} <small>{{r.code||r.subject_code}}</small></td><td class="money">{{yuan(r.balance_cents??r.amount_cents??r.end_cents)}}</td></tr></tbody></table></div></article><article class="card settings-card"><h2>利润基础表</h2><dl class="amount-list"><dt>本期收入</dt><dd>¥{{yuan(financial.income_statement.revenue_cents)}}</dd><dt>本期成本</dt><dd>¥{{yuan(financial.income_statement.cost_cents)}}</dd><dt>本期费用</dt><dd>¥{{yuan(financial.income_statement.expenses_cents)}}</dd><dt>本期净利润</dt><dd><strong>¥{{yuan(financial.income_statement.net_profit_cents)}}</strong></dd><dt>本年累计净利润</dt><dd>¥{{yuan(financial.income_statement.ytd_net_profit_cents)}}</dd></dl><div class="table-wrap"><table class="data-table"><thead><tr><th>损益科目</th><th>本期发生</th></tr></thead><tbody><tr v-for="(r,i) in financial.income_statement.rows||[]" :key="i"><td>{{r.name||r.subject_name}}</td><td>{{yuan(r.amount_cents??r.balance_cents??r.period_cents)}}</td></tr></tbody></table></div></article></div></template>
   </template>

   <template v-if="page==='closing'">
    <div class="notice">操作顺序：审核日常凭证 → 生成损益结转 → 在凭证管理中审核结转凭证 → 结账。只允许按顺序结账；反结账仅允许最近已结期间。</div>
    <div class="card"><div class="table-meta"><h2>会计期间</h2><button class="btn btn-secondary" :disabled="busy" @click="addYear">＋ 添加下一年度</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>会计月份</th><th>状态</th><th>凭证数量</th><th>未审核</th><th>操作</th></tr></thead><tbody><tr v-for="p in periods" :key="p.id||p.month"><td>{{p.month}}</td><td><span class="badge" :class="closed(p)?'success':'warning'">{{closed(p)?'已结账':'未结账'}}</span></td><td>{{(accounting.vouchers||[]).filter(v=>v.account_id===Number(accountId)&&v.date.startsWith(p.month)).length}}</td><td>{{(accounting.vouchers||[]).filter(v=>v.account_id===Number(accountId)&&v.date.startsWith(p.month)&&v.status!=='已完成').length}}</td><td><div class="actions"><button class="table-link" @click="emit('navigate','vouchers',{customer_id:account.customer_id,month:p.month})">查看凭证</button><button v-if="!closed(p)" class="table-link" :disabled="busy||!enabled(account)" @click="periodAction(p,'carryforward')">生成 / 重做结转</button><button v-if="!closed(p)" class="table-link" :disabled="busy||!enabled(account)" @click="periodAction(p,'close')">结账</button><button v-else class="table-link" :disabled="busy" @click="periodAction(p,'unclose')">反结账</button></div></td></tr></tbody></table></div></div>
   </template>
  </template>

  <Teleport to="body"><div v-if="modal" class="modal-mask" @click.self="!busy&&(modal='')"><section class="modal" :class="{'modal-wide':['voucher','opening','view'].includes(modal)}" role="dialog" aria-modal="true" :aria-label="{account:'新建账套',opening:'期初余额',subject:'会计科目',voucher:'记账凭证',view:'凭证详情'}[modal]"><div class="modal-header"><h2>{{{account:'新建客户账套',opening:'期初余额与试算',subject:'会计科目',voucher:form.id?'编辑记账凭证':'新增记账凭证',view:'记账凭证详情'}[modal]}}</h2><button class="btn btn-ghost" aria-label="关闭弹窗" :disabled="busy" @click="modal=''">✕</button></div><div v-if="error" class="notice error" role="alert">{{error}}</div>
   <form v-if="modal==='account'" @submit.prevent="saveAccount"><div class="modal-body form-grid"><label class="field full"><span>所属客户 *</span><select v-model="form.customer_id" required><option value="" disabled>请选择未建立账套的客户</option><option v-for="c in (state.customers||[]).filter(c=>!accounts.some(a=>a.customer_id===c.id))" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="field full"><span>账套名称 *</span><input v-model="form.name" placeholder="例如：示例企业财务账" required maxlength="100"></label><label class="field"><span>启用会计月份 *</span><input v-model="form.start_month" type="month" required></label><div class="notice full">自动建立会计期间和小企业会计准则科目。期初余额试算平衡后方可启用记账。</div></div><div class="modal-footer"><button class="btn btn-secondary" type="button" @click="modal=''">取消</button><button class="btn btn-primary" :disabled="busy">建立账套</button></div></form>
   <form v-if="modal==='subject'" @submit.prevent="saveSubject"><div class="modal-body form-grid"><label class="field"><span>科目编码 *</span><input v-model="form.code" required :disabled="!!form.id" placeholder="如 1002.03"></label><label class="field"><span>科目名称 *</span><input v-model="form.name" required></label><label class="field"><span>上级科目</span><select v-model="form.parent_code" :disabled="!!form.id"><option value="">无（一级科目）</option><option v-for="s in subjects.filter(s=>s.code!=='3103')" :key="s.id" :value="s.code">{{s.code}} {{s.name}}</option></select></label><label class="field"><span>科目类别</span><select v-model="form.type" :disabled="!!form.id"><option>资产</option><option>负债</option><option>权益</option><option>成本</option><option>损益</option></select></label><label class="field"><span>余额方向</span><select v-model="form.direction" :disabled="!!form.id"><option>借</option><option>贷</option></select></label><label v-if="form.id" class="field"><span>状态</span><select v-model="form.active"><option :value="1">启用</option><option :value="0">停用</option></select></label></div><div class="modal-footer"><button class="btn btn-secondary" type="button" @click="modal=''">取消</button><button class="btn btn-primary" :disabled="busy">保存科目</button></div></form>
   <form v-if="modal==='opening'||modal==='voucher'" @submit.prevent="modal==='opening'?saveOpening():saveVoucher()"><div class="modal-body"><div v-if="modal==='voucher'" class="form-grid voucher-meta"><label class="field"><span>凭证日期 *</span><input v-model="form.date" type="date" required></label><label class="field"><span>凭证字</span><select v-model="form.word"><option>记</option><option>收</option><option>付</option><option>转</option></select></label><label class="field"><span>状态</span><select v-model="form.status"><option>草稿</option><option>待复核</option></select></label><label class="field"><span>凭证号</span><input v-model.number="form.number" type="number" min="1" placeholder="留空自动编号"></label><label class="field full"><span>摘要 *</span><input v-model="form.summary" required maxlength="300"></label></div><div v-else class="notice">启用前可反复保存期初余额；借贷必须平衡才能启用。零期初可删除所有行后保存。</div>
    <div class="table-wrap"><table class="data-table entry-table"><thead><tr><th v-if="modal==='voucher'">分录摘要</th><th>会计科目 *</th><th>借方金额（元）</th><th>贷方金额（元）</th><th>操作</th></tr></thead><tbody><tr v-for="(r,i) in (form.entries||form.rows)" :key="i"><td v-if="modal==='voucher'"><input v-model="r.summary" :aria-label="'第'+(i+1)+'行摘要'" placeholder="使用凭证摘要"></td><td><select v-model="r.subject_code" required :aria-label="'第'+(i+1)+'行会计科目'"><option value="" disabled>选择末级科目</option><option v-for="s in leafSubjects" :key="s.id" :value="s.code">{{s.code}} {{s.name}}</option></select></td><td><input v-model="r.debit" type="number" min="0" step="0.01" :aria-label="'第'+(i+1)+'行借方'"></td><td><input v-model="r.credit" type="number" min="0" step="0.01" :aria-label="'第'+(i+1)+'行贷方'"></td><td><button type="button" class="table-link danger-text" @click="(form.entries||form.rows).splice(i,1)">移除</button></td></tr></tbody><tfoot><tr><td v-if="modal==='voucher'"></td><td><strong>合计</strong></td><td class="money">{{yuan(balance.debit)}}</td><td class="money">{{yuan(balance.credit)}}</td><td></td></tr></tfoot></table></div><div class="entry-footer"><button type="button" class="btn btn-secondary" @click="(form.entries||form.rows).push({subject_code:'',summary:'',debit:'',credit:''})">＋ 添加一行</button><span :class="balance.difference===0?'success-text':'danger-text'">{{balance.difference===0?'✓ 借贷平衡':'借贷差额 ¥'+yuan(balance.difference)}}</span></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" :disabled="busy" @click="modal=''">取消</button><button class="btn btn-primary" :disabled="busy">{{busy?'正在保存…':modal==='opening'?'保存期初余额':'保存凭证'}}</button></div></form>
   <div v-if="modal==='view'&&viewed" class="modal-body"><div class="voucher-paper"><h2>记账凭证</h2><p>{{cname(account.customer_id)}} · {{viewed.date}} · {{viewed.word}}-{{viewed.number}} · {{viewed.status}}</p><table class="data-table"><thead><tr><th>摘要</th><th>会计科目</th><th>借方</th><th>贷方</th></tr></thead><tbody><tr v-for="(e,i) in viewed.entries" :key="i"><td>{{e.summary||viewed.summary}}</td><td>{{e.subject_code}} {{sname(e.subject_code)}}</td><td class="money">{{yuan(e.debit_cents)}}</td><td class="money">{{yuan(e.credit_cents)}}</td></tr></tbody></table></div><div class="form-actions"><button class="btn btn-primary" @click="printVoucher(viewed)">打印凭证</button></div></div>
  </section></div></Teleport>
 </section>
</template>
